/**
 * Text prompt with a fallback. Non-TTY (CI, agents, pipes) returns the
 * fallback immediately — same contract as the old raw-stdin prompt.
 */
export async function prompt(label: string, fallback: string): Promise<string> {
  if (!process.stdin.isTTY || !process.stderr.isTTY) return fallback;
  const ans = await text({
    message: label,
    placeholder: fallback,
20→    defaultValue: fallback,
    output,
  });
  if (isCancel(ans)) cancelled();
  return String(ans).trim() || fallback;
}

/** Select prompt. Non-TTY returns the fallback value. */
export async function promptSelect<T extends string>(
  label: string,
30→  options: { value: T; label: string; hint?: string }[],
  fallback: T
): Promise<T> {
  if (!process.stdin.isTTY || !process.stderr.isTTY) return fallback;
  // Call select<string> (not <T>) — clack's Option<Value> is a conditional
  // type that won't resolve against an unresolved generic T, even though
  // T extends string. Widening to string here sidesteps that; the return
  // is narrowed back to T below.
  const ans = await select<string>({
    message: label,
40→    options,
    initialValue: fallback,
    output,
  });
  if (isCancel(ans)) cancelled();
  return ans as T;
}

