      refuseAgentWrite("dora harness new --accept --yes");
      await exit(2);
      return;
    }

    const dir = writeRoutine(home, draft);
    if (!readDefaultMcpUrl(home)) writeDefaultMcpUrl(home, mcpUrl);
    ui.info(`  Wrote ${dir}`);
    ui.blank();
    await exit(0);
  },
});

