  slug: "diagnose-flag-loop",
  dir: "/tmp/diagnose-flag-loop",
  prompt: "ping",
  skillsRun: ["/tmp/skill"],
  skillsRefer: [],
  mcpUrl: "https://example.invalid/mcp",
  interval: "1h",
  maxTick: "10m",
};

function hermes(args: string[]): { exitCode: number; out: string } {
  const r = spawnSync(["hermes", ...args], { stdout: "pipe", stderr: "pipe" });
  return { exitCode: r.exitCode ?? 1, out: `${r.stdout}${r.stderr}` };
}

function helpCmd(args: string[]): string[] {
  const flagsAt = args.findIndex((a) => a.startsWith("-"));
  const path = flagsAt === -1 ? args : args.slice(0, flagsAt);
  const subs = path.filter((a) => !a.startsWith("-") && !a.includes("/") && !a.includes(":") && a !== "ping" && a !== "every 1h");
  // keep only known command words at the front
  const words: string[] = [];
  for (const a of path) {
    if (a.startsWith("-")) break;
    if (["chat", "gateway", "install", "start", "mcp", "add", "test", "login", "tools", "enable", "cron", "create", "pause", "resume", "list"].includes(a)) {
      words.push(a);
    } else break;
  }
  return [...words, "--help"];
}

function flagsOf(args: string[]): string[] {
  const out: string[] = [];
  for (const a of args) {
    if (a.startsWith("--")) out.push(a);
    else if (/^-[a-zA-Z]$/.test(a)) out.push(a);
  }
